	('Q-esl-fast-beginner-1-40-006', 'esl-fast-beginner-1-40', 'What do the magicians take out of their hats?', 'Các ảo thuật gia lấy gì ra khỏi mũ?', 'ACTIVE', NULL, NULL, NULL, NULL),
	('Q-esl-fast-beginner-1-40-007', 'esl-fast-beginner-1-40', 'Where do people walk on a rope?', 'Mọi người đi trên dây ở đâu?', 'ACTIVE', NULL, NULL, NULL, NULL),
	('Q-esl-fast-beginner-1-40-008', 'esl-fast-beginner-1-40', 'What do people juggle?', 'Mọi người tung hứng gì?', 'ACTIVE', NULL, NULL, NULL, NULL),
	('Q-esl-fast-beginner-1-40-009', 'esl-fast-beginner-1-40', 'What else does the girl see at the circus?', 'Cô bé còn nhìn thấy gì ở rạp xiếc?', 'ACTIVE', NULL, NULL, NULL, NULL),
	('Q-esl-fast-beginner-1-40-010', 'esl-fast-beginner-1-40', 'What animals does the girl see?', 'Cô bé nhìn thấy những con vật nào?', 'ACTIVE', NULL, NULL, NULL, NULL),
	('Q-esl-fast-beginner-1-40-011', 'esl-fast-beginner-1-40', 'What do the lions jump through?', 'Những con sư tử nhảy qua cái gì?', 'ACTIVE', NULL, NULL, NULL, NULL),
	('Q-esl-fast-beginner-1-40-012', 'esl-fast-beginner-1-40', 'What do the elephants do?', 'Những chú voi làm gì?', 'ACTIVE', NULL, NULL, NULL, NULL),
