	('Q-esl-fast-beginner-1-40-014', 'esl-fast-beginner-1-40', 'How does the girl feel about the circus?', 'Cô bé cảm thấy thế nào về rạp xiếc?', 'ACTIVE', NULL, NULL, NULL, NULL),
	('Q-esl-fast-beginner-1-40-015', 'esl-fast-beginner-1-40', 'Who is very colorful?', 'Ai trông rất sặc sỡ?', 'ACTIVE', NULL, NULL, NULL, NULL),
