	('Q-esl-fast-beginner-1-40-018', 'esl-fast-beginner-1-40', 'What are people walking on?', 'Mọi người đang đi trên cái gì?', 'ACTIVE', NULL, NULL, NULL, NULL),
	('Q-esl-fast-beginner-1-40-019', 'esl-fast-beginner-1-40', 'What are the people juggling?', 'Mọi người đang tung hứng những gì?', 'ACTIVE', NULL, NULL, NULL, NULL),
	('Q-esl-fast-beginner-1-40-020', 'esl-fast-beginner-1-40', 'Are there many animals at the circus?', 'Có nhiều con vật ở rạp xiếc không?', 'ACTIVE', NULL, NULL, NULL, NULL),
	('Q-esl-fast-beginner-1-40-021', 'esl-fast-beginner-1-40', 'Which animals jump through hoops of fire?', 'Con vật nào nhảy qua những vòng lửa?', 'ACTIVE', NULL, NULL, NULL, NULL),
	('Q-esl-fast-beginner-1-40-022', 'esl-fast-beginner-1-40', 'Which animals can dance?', 'Con vật nào có thể nhảy múa?', 'ACTIVE', NULL, NULL, NULL, NULL),
	('Q-esl-fast-beginner-1-40-023', 'esl-fast-beginner-1-40', 'What color is the clown?', 'Chú hề có màu gì?', 'ACTIVE', NULL, NULL, NULL, NULL),
	('Q-esl-fast-beginner-1-40-024', 'esl-fast-beginner-1-40', 'What does the girl see after the magicians?', 'Sau các ảo thuật gia, cô bé nhìn thấy gì?', 'ACTIVE', NULL, NULL, NULL, NULL),
	('Q-esl-fast-beginner-1-40-025', 'esl-fast-beginner-1-40', 'What does the girl see in the air?', 'Cô bé nhìn thấy gì ở trên không?', 'ACTIVE', NULL, NULL, NULL, NULL),
	('Q-esl-fast-beginner-1-40-026', 'esl-fast-beginner-1-40', 'What do the lions jump through?', 'Những con sư tử nhảy qua cái gì?', 'ACTIVE', NULL, NULL, NULL, NULL),
	('Q-esl-fast-beginner-1-40-027', 'esl-fast-beginner-1-40', 'Does the girl see elephants?', 'Cô bé có nhìn thấy voi không?', 'ACTIVE', NULL, NULL, NULL, NULL),
	('Q-esl-fast-beginner-1-40-028', 'esl-fast-beginner-1-40', 'Does the girl see magicians?', 'Cô bé có nhìn thấy các ảo thuật gia không?', 'ACTIVE', NULL, NULL, NULL, NULL),
	('Q-esl-fast-beginner-1-40-029', 'esl-fast-beginner-1-40', 'Does the girl enjoy the circus?', 'Cô bé có thích rạp xiếc không?', 'ACTIVE', NULL, NULL, NULL, NULL),
	('Q-esl-fast-beginner-1-40-030', 'esl-fast-beginner-1-40', 'Why does the girl not want to leave the circus?', 'Tại sao cô bé không muốn rời rạp xiếc?', 'ACTIVE', NULL, NULL, NULL, NULL);
	
